-- Faixas de CEP por UF e município (código IBGE). Fonte: base pública de faixas de CEP
-- (gists tamnil/hugosenari, arquivo TABELA/ceps.csv), com as cidades casadas com ibge_municipalities em 2026-11-19.
-- Faixas sem município cobrem a UF inteira.
CREATE TABLE postal_code_ranges (
    cep_start char(8) NOT NULL CHECK (cep_start ~ '^[0-9]{8}$'),
    cep_end char(8) NOT NULL CHECK (cep_end ~ '^[0-9]{8}$'),
    state_code smallint NOT NULL REFERENCES ibge_states(code),
    municipality_code integer REFERENCES ibge_municipalities(code),
    PRIMARY KEY (state_code, cep_start, cep_end),
    CHECK (cep_start <= cep_end)
);
CREATE INDEX postal_code_ranges_lookup_idx ON postal_code_ranges(cep_start, cep_end);
CREATE INDEX postal_code_ranges_municipality_idx ON postal_code_ranges(municipality_code);


DO $$ BEGIN
  IF EXISTS (SELECT FROM pg_roles WHERE rolname = 'erp_next_app') THEN GRANT SELECT ON postal_code_ranges TO erp_next_app; END IF;
END $$;
